const $=id=>document.getElementById(id);let items=[],selected=-1,busy=false,photo=null,worker=null,stopRequested=false,nextId=1;
const labels={pending:'Ready',processing:'Straightening…',corrected:'Straightened',unchanged:'No correction detected',unresolved:'Could not straighten automatically',error:'Could not process'};
function message(text,detail=''){$('status').textContent=text;$('detail').textContent=detail}
function controls(){document.body.classList.toggle('busy',busy);for(let id of ['choose','replace','clear'])$(id).disabled=busy;for(let b of $('queue').querySelectorAll('button'))b.disabled=busy;$('submit').disabled=busy||!items.some(i=>i.status==='pending');$('submit').textContent=busy?'Working…':items.length>1?'Straighten all':'Straighten';$('download').disabled=busy||!items[selected]?.result;$('downloadAll').disabled=busy||!items.some(i=>i.result);$('batch').hidden=!items.length;$('batchCount').textContent=`${items.length} photo${items.length===1?'':'s'} · ${items.filter(i=>i.result).length} processed`}
function queue(){const el=$('queue');el.replaceChildren();items.forEach((item,index)=>{let button=document.createElement('button');button.className='queueitem'+(index===selected?' selected':'');button.setAttribute('aria-pressed',index===selected?'true':'false');let name=document.createElement('span'),state=document.createElement('small');name.textContent=`${index+1}. ${item.file.name}`;state.textContent=labels[item.status];button.append(name,state);button.onclick=()=>select(index);el.append(button)});controls()}
async function decode(file){let url=URL.createObjectURL(file);try{let img=new Image();img.src=url;await img.decode();if(img.width*img.height>60000000||Math.max(img.width,img.height)>20000)throw Error('Resize below 60 megapixels and 20,000 pixels per side.');if(Math.min(img.width,img.height)<80)throw Error('Use a photo at least 80 pixels on each side.');return {img,url}}catch(e){URL.revokeObjectURL(url);throw e}}
let displayedURL=null,viewRevision=0;
async function select(index){selected=index;let rev=++viewRevision,item=items[index];if(!item)return;queue();$('drop').hidden=true;$('previews').hidden=false;$('replace').hidden=false;$('fileLabel').textContent=item.file.name;if(displayedURL)URL.revokeObjectURL(displayedURL);displayedURL=URL.createObjectURL(item.file);$('originalImage').src=displayedURL;$('resultCanvas').hidden=true;comparisonReady(false);$('pending').hidden=false;$('pendingText').textContent=item.status==='error'?item.error:item.status==='processing'?'Analysing the camera angle…':'Your straightened photo will appear here.';$('resultLabel').textContent=item.result?labels[item.status].toUpperCase():'RESULT';$('download').hidden=!item.result;$('download').textContent=item.status==='corrected'?'Download PNG':'Download original PNG';if(!busy)message(item.result?.message||item.error||'Ready to straighten.');if(item.preview){let u=URL.createObjectURL(item.preview);try{let img=new Image();img.src=u;await img.decode();if(rev!==viewRevision)return;let c=$('resultCanvas');c.width=img.width;c.height=img.height;c.getContext('2d').drawImage(img,0,0);c.hidden=false;comparisonReady(true);fitComparison();$('pending').hidden=true}finally{URL.revokeObjectURL(u)}}controls()}
async function addFiles(files){if(busy)return;let added=0,skipped=0;for(let file of files){if(items.length>=100){skipped=files.length-added;break}let error=null;if(file.size>40*1024*1024)error='This file exceeds 40 MB.';else if(!['image/jpeg','image/png','image/webp'].includes(file.type))error='Use JPEG, PNG or WebP. Convert HEIC or RAW first.';items.push({id:nextId++,file,status:error?'error':'pending',error,result:null,preview:null});added++}if(selected<0&&items.length)await select(0);queue();if(added)message(`${added} photo${added===1?'':'s'} added.`, skipped?`${skipped} files were not added: the batch limit is 100 photos.`:'Unsupported files are marked individually; the rest can still be processed.');$('file').value=''}
for(let id of ['choose','replace'])$(id).onclick=()=>$('file').click();$('file').onchange=e=>addFiles(Array.from(e.target.files));let drop=$('drop');for(let type of ['dragenter','dragover'])drop.addEventListener(type,e=>{e.preventDefault();if(!busy)drop.classList.add('drag')});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));window.addEventListener('dragover',e=>e.preventDefault());window.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');if(e.dataTransfer.files.length)addFiles(Array.from(e.dataTransfer.files))});$('clear').onclick=()=>{if(busy)return;items=[];selected=-1;viewRevision++;if(displayedURL)URL.revokeObjectURL(displayedURL);displayedURL=null;$('originalImage').removeAttribute('src');$('resultCanvas').width=1;$('previews').hidden=true;$('drop').hidden=false;$('replace').hidden=true;$('download').hidden=true;$('fileLabel').textContent='Your photos';queue();message('Choose photos to get started.')};
async function processItem(item){try{const response=await PythonEngine.process(item.file);item.preview=response.blob;item.result=response.result;item.status=response.result.status;}catch(e){item.status='error';item.error=e.message||'Python could not process this photo.';}}
async function straighten(){if(busy)throw Error('Processing is already in progress.');let pending=items.filter(i=>i.status==='pending');if(!pending.length)throw Error('Add photos to process first.');busy=true;stopRequested=false;$('stop').hidden=false;$('stop').disabled=false;controls();let done=0;try{for(let item of pending){if(stopRequested)break;item.status='processing';await select(items.indexOf(item));message(`Straightening ${done+1} of ${pending.length}…`,item.file.name);await processItem(item);done++;await select(items.indexOf(item));queue()}let failed=items.filter(i=>i.status==='error').length;message(stopRequested?`Stopped after ${done} photo${done===1?'':'s'}. You can resume the remaining queue.`:`Finished ${done} photo${done===1?'':'s'}. Select any photo to review it.`,failed?`${failed} file${failed===1?'':'s'} could not be processed; see the queue.`:'Download individual results or all processed photos as a ZIP.');return {processed:done,remaining:items.filter(i=>i.status==='pending').length,errors:failed}}finally{busy=false;$('stop').hidden=true;controls()}}
$('submit').onclick=()=>straighten().catch(e=>message(e.message));$('stop').onclick=()=>{stopRequested=true;$('stop').disabled=true;message('Stopping after the current photo…')};
async function exportItem(item){return (await PythonEngine.export(item.file,item.result.params)).blob;}
function outputName(item){let stem=item.file.name.replace(/\.[^.]+$/,'').replace(/[\\/:*?"<>|\x00-\x1f]/g,'_');return `${String(items.indexOf(item)+1).padStart(3,'0')}-${stem.slice(0,150)}-${item.status==='corrected'?'straightened':item.status==='unresolved'?'unresolved-original':'unchanged-original'}.png`}
function downloadBlob(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000)}
$('download').onclick=async()=>{let item=items[selected];if(busy||!item?.result)return;busy=true;controls();message('Preparing your full-resolution PNG…');try{downloadBlob(await exportItem(item),outputName(item));message('Your PNG download is ready.','Original pixel dimensions · lossless PNG · original metadata not included.')}catch(e){message(e.message)}finally{busy=false;controls()}};
$('downloadAll').onclick=async()=>{if(busy)return;let ready=items.filter(i=>i.result);if(!ready.length)return;busy=true;controls();let entries=[],total=0,report=[];try{for(let i=0;i<ready.length;i++){let item=ready[i];message(`Preparing ZIP: ${i+1} of ${ready.length}…`,item.file.name);try{let blob=await exportItem(item);total+=blob.size;if(total>512*1024*1024)throw Error('ZIP_LIMIT');let name=outputName(item);entries.push({name,blob});report.push({original:item.file.name,output:name,status:item.status,message:item.result.message,evidence:item.result.evidence})}catch(e){if(e.message==='ZIP_LIMIT')throw Error('This ZIP would exceed 512 MB. Download the results individually or use a smaller batch.');report.push({original:item.file.name,status:'export-error',message:e.message})}}for(let item of items.filter(i=>!i.result))report.push({original:item.file.name,status:item.status,message:item.error||'Not processed'});entries.push({name:'batch-results.json',blob:new Blob([JSON.stringify(report,null,2)],{type:'application/json'})});message('Assembling your ZIP…');downloadBlob(await BatchZip.create(entries),'straightline-results.zip');message('Your ZIP download is ready.','Unresolved and unchanged photos are labelled as originals; the ZIP includes a status report.')}catch(e){message(e.message)}finally{busy=false;controls()}};
if(document.modelContext?.registerTool){let life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});for(let tool of [{name:'straighten_uploaded_photos',description:'Process all pending photos in the visible batch without downloading files.',annotations:{readOnlyHint:false,untrustedContentHint:false},execute:straighten},{name:'get_straightening_status',description:'Read batch progress and per-photo results.',annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async()=>({processing:busy,items:items.map(i=>({name:i.file.name,status:i.status}))})}]){let action=tool.execute;tool.inputSchema={type:'object',properties:{},additionalProperties:false};tool.execute=async input=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw Error('Expected an empty object.');return action()};try{Promise.resolve(document.modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{})}catch(e){}}}
controls();

function setComparison(value){let n=Math.max(0,Math.min(100,Number(value)||0));$('compareSlider').value=n;$('comparisonFrame').style.setProperty('--split',n+'%');$('compareSlider').setAttribute('aria-valuetext',Math.round(n)+'% original, '+Math.round(100-n)+'% result')}
function comparisonReady(ready){for(let id of ['afterLayer','divider','compareSlider','resultLabel'])$(id).hidden=!ready;$('compareHint').textContent=ready?'Preview · downloads use original pixel dimensions':'Straighten a photo to compare it.';setComparison(50)}
function fitComparison(){const img=$('originalImage'),stage=$('comparisonStage');if(!img.naturalWidth||!img.naturalHeight)return;const maxWidth=Math.max(1,stage.clientWidth-24),maxHeight=Math.max(240,Math.min(780,window.innerHeight*.7)),scale=Math.min(maxWidth/img.naturalWidth,maxHeight/img.naturalHeight);$('comparisonFrame').style.width=Math.round(img.naturalWidth*scale)+'px';$('comparisonFrame').style.height=Math.round(img.naturalHeight*scale)+'px'}
$('originalImage').addEventListener('load',fitComparison);window.addEventListener('resize',fitComparison);
$('compareSlider').addEventListener('input',e=>setComparison(e.target.value));
let dragging=false;function pointerSplit(e){const r=$('comparisonFrame').getBoundingClientRect();setComparison((e.clientX-r.left)/r.width*100)}
$('compareSlider').addEventListener('pointerdown',e=>{e.preventDefault();dragging=true;e.currentTarget.focus();e.currentTarget.setPointerCapture(e.pointerId);pointerSplit(e)});
$('compareSlider').addEventListener('pointermove',e=>{if(dragging)pointerSplit(e)});
for(let name of ['pointerup','pointercancel','lostpointercapture'])$('compareSlider').addEventListener(name,()=>{dragging=false});
